from collections import deque

def transform(num, operations):
    num_str = str(num)
    for op in operations:
        d, s = op
        if s == 1:
            num_str = str(int(num_str[:d]) + 1) + num_str[d:]
        else:
            num_str = str(int(num_str[:d]) - 1) + num_str[d:]
    return int(num_str)

def solve(n, a, b):
    if sorted(str(a)) != sorted(str(b)):
        return -1

    visited = set()
    queue = deque([(a, [])])

    while queue:
        current, operations = queue.popleft()
        if current == b:
            return len(operations), operations

        current_str = str(current)
        for i in range(n - 1):
            for sign in [1, -1]:
                if 0 <= int(current_str[i]) + sign < 10 and 0 <= int(current_str[i + 1]) + sign < 10:
                    new_num = transform(current, [(i + 1, sign)])
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append((new_num, operations + [(i + 1, sign)]))
    return -1

# Read input
n = int(input().strip())
a = int(input().strip())
b = int(input().strip())

# Solve the problem
result = solve(n, a, b)

# Output the result
if result == -1:
    print(-1)
else:
    c, moves = result
    print(c)
    for move in moves:
        print(*move)
